def missing_keys(cfg: Dict[str, Any]) -> list[str]:
    """Required policy keys that are absent from `cfg`, as dotted names."""
    absent = []
    for section, key in REQUIRED_KEYS:
        if key not in (cfg.get(section) or {}):
            absent.append(f"{section}.{key}")
    return absent


def require(cfg: Dict[str, Any]) -> Dict[str, Any]:
    absent = missing_keys(cfg)
    if absent:
        raise KeyError(f"policy is missing required keys: {', '.join(absent)}")
    return cfg


def code_columns(cfg: Dict[str, Any]) -> list[str]:
    """Diagnosis columns the register is built from.

    The contract names these columns. A release bundle has been observed to ship
    the policy without `register.code_columns` even when the working tree has it,
    so the known chart columns are the fallback rather than a hard failure.
    """
    register = cfg.get("register") or {}
    columns = register.get("code_columns")
