import json, socket
SOCKET="/run/envd/envd.sock"

def call(op, args=None):
    sock = socket.socket(socket.AF_UNIX, socket.SOCK_STREAM)
    sock.settimeout(30)
    sock.connect(SOCKET)
    sock.sendall(json.dumps({"op": op, "args": args or {}}).encode()+b"\n")
    buf=b""
    while not buf.endswith(b"\n"):
        c=sock.recv(1<<20)
        if not c: break
        buf += c
    sock.close()
    try:
        return json.loads(buf.decode())
    except Exception as e:
        return {"raw": buf[:500].decode(), "err": str(e)}

for op in ["incident.read", "remediate", "canary.open", "canary.read", "cutover.commit", "deploy.prepare", "status"]:
